import { z } from "zod";
import {
  BUYING_ROLES,
  ENGAGEMENT_LEVELS,
  SENIORITIES,
  STAGES,
  TIERS,
  TOUCH_CHANNELS,
} from "@/lib/domain/enums";

/**
 * ACC Data Contract v1 (Phase 13): a neutral, versioned file format other systems can produce and ACC imports
 * (with preview, dedupe and undo), and that ACC exports. It carries account knowledge the user is allowed to hold;
 * it deliberately has NO fields for personal contact details (email, phone, address) or pricing/margins.
 * JSON Schema: docs/contract/acc-data-v1.schema.json (generated by `npm run contract:schema`).
 */
export const CONTRACT_FORMAT = "acc-data";
export const CONTRACT_VERSION = "1.0";

const s = (max = 500) => z.string().trim().max(max);
const id = z.string().trim().min(1).max(200);
const date = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}/, "ISO date, e.g. 2026-11-30")
  .describe("ISO 8601 date or date-time");

/** Points at an account: by the sender's id (previously imported), or by domain, or by exact name. */
export const AccountRefSchema = z
  .object({ externalId: id.optional(), domain: s(253).optional(), name: s(200).optional() })
  .refine(
    (r) => r.externalId || r.domain || r.name,
    "An account reference needs externalId, domain or name",
  )
  .describe("Reference to an account in the same file or already in ACC");

const keys = {
  externalId: id
    .optional()
    .describe("The record's id in the sending system; keeps identity across re-imports"),
  accId: id.optional().describe("ACC's own id (present on ACC exports; ignored on import)"),
  sourceUrl: z
    .url({ protocol: /^https?$/ })
    .max(2000)
    .optional()
    .describe(
      "Where the sending system found this record (a Glean result, a CRM record link). Kept as provenance.",
    ),
  externalRefs: z
    .record(z.string().max(80), id)
    .optional()
    .describe(
      "This record's ids in other systems, keyed by system (ACC exports include ids it was imported with)",
    ),
};

export const ContractAccountSchema = z.object({
  ...keys,
  name: s(200).min(1),
  domain: s(253).optional(),
  ticker: s(12).optional(),
  industry: s(120).optional(),
  subIndustry: s(120).optional(),
  hq: s(200).optional(),
  tier: z.enum(TIERS).optional(),
  employeeBand: s(40).optional(),
  revenueBand: s(40).optional(),
  ownerNotes: s(4000).optional().describe("internal"),
});

export const ContractContactSchema = z.object({
  ...keys,
  account: AccountRefSchema,
  displayName: s(120)
    .optional()
    .describe("Name as the user entered it; no personal contact details in this format"),
  title: s(160).min(1),
  function: s(80).optional(),
  seniority: z.enum(SENIORITIES).optional(),
  buyingRole: z.enum(BUYING_ROLES).optional(),
  engagement: z.enum(ENGAGEMENT_LEVELS).optional(),
});

export const ContractOpportunitySchema = z.object({
  ...keys,
  account: AccountRefSchema,
  name: s(200).min(1),
  practiceArea: s(60).min(1).describe("Practice area id or label, e.g. modern-dc"),
  stage: z.enum(STAGES),
  amount: z
    .number()
    .min(0)
    .max(1e12)
    .optional()
    .describe("internal; omitted from customer-safe files"),
  closeDate: date,
  probability: z.number().int().min(0).max(100).optional().describe("internal"),
  nextStep: s(500).optional(),
  nextStepDate: date.optional(),
});

export const ContractActivitySchema = z.object({
  ...keys,
  account: AccountRefSchema,
  channel: z.enum(TOUCH_CHANNELS),
  persona: s(120).min(1).describe("Role or title engaged, e.g. VP Infrastructure"),
  date: date,
  completed: z.boolean().default(true),
  outcome: z.enum(["replied", "meeting", "opp-created", "no-response"]).optional(),
  summary: s(500).optional(),
});

export const ContractNoteSchema = z.object({
  ...keys,
  account: AccountRefSchema,
  body: s(20000).min(1).describe("internal"),
  date: date.optional(),
});

export const ContractTaskSchema = z.object({
  ...keys,
  account: AccountRefSchema.optional(),
  title: s(200).min(2),
  dueDate: date.optional(),
  priority: z.enum(["high", "normal", "low"]).optional(),
  status: z.enum(["open", "done", "cancelled"]).optional(),
});

export const ContractPartnerRepSchema = z.object({
  ...keys,
  partnerCompany: s(120).min(2),
  name: s(120).min(2),
  title: s(120).optional(),
  territory: s(120).optional(),
  accounts: z.array(AccountRefSchema).max(500).default([]),
});

export const ContractSchema = z.object({
  format: z.literal(CONTRACT_FORMAT),
  version: z.string().regex(/^1\.\d+$/, "This ACC reads contract version 1.x"),
  exportedAt: z.string().optional(),
  source: z.object({
    system: s(80)
      .min(1)
      .describe("Sending system, e.g. 'acc' or 'internal-tool'. Scopes externalIds."),
    note: s(500).optional(),
  }),
  /** "customer-safe" files never contain fields described as internal. */
  visibility: z.enum(["internal", "customer-safe"]).default("internal"),
  entities: z.object({
    accounts: z.array(ContractAccountSchema).max(5000).default([]),
    contacts: z.array(ContractContactSchema).max(20000).default([]),
    opportunities: z.array(ContractOpportunitySchema).max(10000).default([]),
    activities: z.array(ContractActivitySchema).max(50000).default([]),
    notes: z.array(ContractNoteSchema).max(20000).default([]),
    tasks: z.array(ContractTaskSchema).max(20000).default([]),
    partnerReps: z.array(ContractPartnerRepSchema).max(2000).default([]),
  }),
});
export type Contract = z.infer<typeof ContractSchema>;
export type AccountRef = z.infer<typeof AccountRefSchema>;
export type ContractEntities = Contract["entities"];
export const ENTITY_KEYS = [
  "accounts",
  "contacts",
  "opportunities",
  "activities",
  "notes",
  "tasks",
  "partnerReps",
] as const;

/** Fields described "internal" are dropped from customer-safe exports (and whole `notes`). */
export const INTERNAL_FIELDS: Partial<Record<keyof ContractEntities, string[]>> = {
  accounts: ["ownerNotes"],
  opportunities: ["amount", "probability"],
};

/** The generated JSON Schema for docs and the sending system's validator. */
export const contractJsonSchema = () =>
  z.toJSONSchema(ContractSchema, { target: "draft-2020-12", io: "input" });
